/* @lc app=leetcode id=3995 lang=kotlin */ class Solution { fun minCost(source: String, target: String, rules: List<List<String>>, costs: IntArray): Int = source.length.let { n -> LongArray(n + 1) { if (it == 0) 0L else Long.MAX_VALUE / 4 }.also { dp -> (0 until n).forEach { i -> (if (source[i] == target[i]) listOf(i + 1 to dp[i]) else emptyList()).plus(rules.indices.filter { r -> i + rules[r][0].length <= n && rules[r][0].indices.all { j -> rules[r][0][j] == '*' || rules[r][0][j] == source[i + j] } && target.startsWith(rules[r][1], i) }.map { r -> i + rules[r][0].length to dp[i] + costs[r] + rules[r][0].count { it == '*' } }).forEach { (j, v) -> dp.set(j, minOf(dp[j], v)) } } }.let { if (it[n] >= Long.MAX_VALUE / 8) -1 else it[n].toInt() } } }